update cms_activity set cancellation_receipt_json = #{receipt} where id = #{id}

    and cancellation_receipt_json is null

        and JSON_UNQUOTE(JSON_EXTRACT(cancellation_receipt_json, '$.state')) = 'PENDING'
        and JSON_UNQUOTE(JSON_EXTRACT(cancellation_receipt_json, '$.requestHash')) = #{requestHash}

mapper.select:
select id, member_id, name, description, img_url, img_arr, category_ids, address_name, longitude, latitude,

    ROUND(st_distance_sphere(point(#{longitude},#{latitude}),point(IFNULL(longitude,0), IFNULL(latitude,0)))) distance,

address, status,publish_status, cancel_time, reason, del_flag,start_date,end_date,template_id,
topic_id, club_id, create_by, create_time, update_by, update_time,
(select t.product_type from cms_topic t where t.id = cms_activity.topic_id) as product_type
from cms_activity

     and member_id = #{memberId}
     and name like concat('%', #{name}, '%')
     and description = #{description}
     and img_url = #{imgUrl}
     and img_arr = #{imgArr}
      AND FIND_IN_SET(#{categoryIds}, category_ids) > 0
     and address_name like concat('%', #{addressName}, '%')
     and address = #{address}
     and status = #{status}
     and publish_status = #{publishStatus}
     and topic_id = #{topicId}
     and club_id = #{clubId}
     and (club_id is null or club_id = 0)
     and cancel_time is null
     and del_flag = #{delFlag}

        and (club_id is null or club_id = 0 or exists (
            select 1 from club active_club
            where active_club.id = cms_activity.club_id and active_club.del_flag = 0
        ))
        and not exists (
            select 1
            from cms_topic parent_topic
            left join club parent_club
              on parent_club.id = parent_topic.club_id and parent_club.del_flag = 0
            where parent_topic.id = cms_activity.topic_id
              and parent_topic.club_id is not null and parent_topic.club_id != 0
              and parent_club.id is null
        )

     and reason = #{reason}

     and check_status = #{checkStatus}
     and is_settlement = #{isSettlement}

     and id in (select data_id from cms_activity_like where member_id=#{isLikedMemberId}) 


        and create_time >= #{startTime}


        and create_time <= #{endTime}



        and start_date >= #{startDate}


        and end_date <= #{endTime}

     and end_date > now() 


        and ROUND(st_distance_sphere(point(#{longitude},#{latitude}),point(IFNULL(longitude,0), IFNULL(latitude,0)))) < 100000






        order by

        distance,

        create_time desc



    order by

        distance,

    create_time desc

mapper.update:
update cms_activity
name = #{name}, description = #{description}, img_url = #{imgUrl}, img_arr = #{imgArr}, category_ids = #{categoryIds}, address_name = #{addressName}, longitude = #{longitude}, latitude = #{latitude}, address = #{address}, day_note = #{dayNote}, start_date = #{startDate}, end_date = #{endDate}, template_id = #{templateId}, update_by = #{updateBy}, update_time = #{updateTime},
where id = #{id} and member_id = #{memberId}
